function validate([rungs, dist]) {
  if (!Array.isArray(rungs) || rungs.length < 1 || rungs.length > 100000) return 'rungs needs 1 to 100000 heights.';
  if (rungs.some(h => !Number.isInteger(h) || h < 1 || h > 1e9)) return 'Each height is an integer between 1 and 10^9.';
  for (let i = 1; i < rungs.length; i++) if (rungs[i] <= rungs[i - 1]) return 'rungs must be strictly increasing.';
  if (!Number.isInteger(dist) || dist < 1 || dist > 1e9) return 'dist is an integer between 1 and 10^9.';
  return null;
}

