function addRungs(rungs, dist) {
  // For each gap, binary search the fewest climbs of length at most dist that cover it; each extra climb needs one new rung.
  let count = 0, current = 0;
  for (const rung of rungs) {
    const gap = rung - current;
    let lo = 1, hi = gap;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (mid * dist >= gap) hi = mid; else lo = mid + 1;
    }
    count += lo - 1;
    current = rung;
  }
  return count;
}

