function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const values = new Set();
    while (values.size < n) values.add(pick(1, 40));
    return [[...values].sort((a, b) => a - b), pick(1, 12)];
  }
  const n = 2000;
  const maxGap = [5, 1000, 500000][pick(0, 2)];
  const rungs = [];
  let height = 0;
  for (let i = 0; i < n; i++) {
    height += pick(1, maxGap);
    rungs.push(height);
  }
  const dist = [pick(1, 3), pick(1, 1000), pick(1, 1000000000)][pick(0, 2)];
  return [rungs, dist];
}
